\begin{ex}%[9H5V1-5]
Cho tam giác ${ABC}$ cân tại ${A}$ có $\widehat{A}=120^{\circ}$ nội tiếp đường tròn ${(O; 3cm)}$. Khi đó diện tích tam giác ${ABC}$ là: 
\choice
{ \True $\dfrac{9 \sqrt{3}}{4} cm^{2}$  }
   { $\dfrac{9 \sqrt{6}}{2}cm^{2}$  }
     { $\dfrac{3 \sqrt{3}}{4}cm^{2}$  }
    { $\dfrac{9 \sqrt{3}}{2}cm^{2}$  }
\loigiai{
\begin{tikzpicture}

    % Vẽ đường tròn tâm O bán kính 3cm
    \draw[thick] (0,0) circle (3cm);

    % Định nghĩa các điểm A, O
    \coordinate [label=above:$A$] (A) at (0,3);
    \coordinate [label=below:$O$] (O) at (0,0);

    % Xác định tọa độ điểm B và C trên đường tròn sao cho tam giác ABC cân tại A với góc BAC = 120 độ
    \coordinate [label=below left:$B$] (B) at ({3*cos(150)},{3*sin(150)});
    \coordinate [label=below right:$C$] (C) at ({3*cos(30)},{3*sin(30)});

    % Xác định điểm H là trung điểm của BC
    \coordinate [label=below:$H$] (H) at ($(B)!0.5!(C)$);

    % Vẽ tam giác ABC
    \draw[thick] (B) -- (A) -- (C) -- cycle;

    % Nối A, H, O
    \draw[thick] (A) -- (H);
    \draw[thick] (O) -- (H);

    % Vẽ các đoạn thẳng nối các điểm với tâm đường tròn O
    \draw[dashed] (O) -- (A);
    \draw[dashed] (O) -- (B);
    \draw[dashed] (O) -- (C);

    % Vẽ các điểm A, B, C, O và H
    \fill (A) circle (2pt);
    \fill (B) circle (2pt);
    \fill (C) circle (2pt);
    \fill (O) circle (2pt);
    \fill (H) circle (2pt);

\end{tikzpicture}
Kẻ ${AH} \bot {BC}$ tại ${H}$. Ta có ${AH}$ là đường trung trực của ${BC}$\\
Nên ${AH}$ đi qua ${O}$ và $\Delta AOC$ đều, do đó $HC=\dfrac{R\sqrt{3} }{2}$, $HA=\dfrac{R}{2}$\\
Vì vậy diện tích tam giác ${ABC}$ bằng $\dfrac{1}{2}.BC.AH=HC.HA= \dfrac{R\sqrt{3} }{2}.\dfrac{R}{2}= \dfrac{R^{2}.\sqrt{3} }{4}= \dfrac{9 \sqrt{3}}{4}$
}\end{ex}

